28	    public static String label(LocalDate date) {
29	        return String.format("FY%02d", of(date) % 100);
30	    }
31	
32	    /** Whole fiscal years elapsed from {@code from} to {@code to} (0 within the same fiscal year). */
33	    public static int elapsed(LocalDate from, LocalDate to) {
